const client = new RedwoodClient();
const stream = client.startStream({ model: 'redwood-1', prompt });
stream.on('data', (chunk) => {
  if (chunk.type === 'checkpoint') { localStorage.setItem('last_checkpoint', chunk.token); }
  if (chunk.type === 'tool_call') {
    const key = chunk.tool.idempotency_key || genKey();
    if (!toolCache.has(key)) { toolCache.set(key, callTool(chunk.tool)); }
  }
});
const token = localStorage.getItem('last_checkpoint');
if (token) { client.resumeStream({ checkpoint: token }).on('data', handleChunk); }

