from redwood import RedwoodClient
client = RedwoodClient()
ck = None
with client.start_stream(model='redwood-1', prompt=prompt) as s:
  for ev in s:
    if ev.get('type') == 'checkpoint':
      ck = ev['token']; open('/tmp/ck','w').write(ck)
    if ev.get('type') == 'tool_call':
      key = ev['tool'].get('idempotency_key') or generate_key()
      if not tool_cache.contains(key):
        res = call_tool(ev['tool']); tool_cache.store(key,res)
# resume from saved token
if os.path.exists('/tmp/ck'):
  token = open('/tmp/ck').read().strip()
