client := redwood.NewClient()
stream := client.StartStream(ctx, redwood.StreamParams{Model: "redwood-1", Prompt: prompt})
for stream.Next() { ev := stream.Event(); switch ev.Type {
case redwood.EventCheckpoint: os.WriteFile('/var/tmp/ck', []byte(ev.Token), 0644)
case redwood.EventToolCall: key := ev.Tool.IdempotencyKey; if !toolCache.Has(key) { res := callTool(ev.Tool); toolCache.Put(key,res) }
} }
if data, err := os.ReadFile('/var/tmp/ck'); err == nil { token := string(data); rstream := client.ResumeStream(ctx, token); /* consume rstream */ }
